// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.llm.registryimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport timber.log.Timberimport java.util.concurrent.ConcurrentHashMapimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Local LLM model catalog. * * Registry for downloadable on-device LLM models (GGUF format). User can: *   - Browse built-in catalog (popular Qwen, Llama, Phi models) *   - Add custom models via URL (any Hugging Face / GitHub GGUF link) *   - Add custom models via local file path (sideloaded GGUF files) *   - Delete downloaded models to free up storage *   - Set a default model for the LocalLlmProvider to load on app start * * ## Why a Catalog? * * New models launch every week (Qwen 2.5 → 3, Llama 3 → 3.1 → 4, Phi-3 → 4). * Hardcoding a single model in code would lock NOUS to that model. Instead, * the catalog is user-editable — when a new model launches, user just adds * its URL to the catalog without needing an app update. * * ## Storage * *   - **Catalog metadata** (model name, URL, size, context length): in-memory *     for Module 2; Room-backed in Module 3 (`local_models` table). *   - **Downloaded GGUF files**: app's internal storage at *     `files/models/{modelId}.gguf` (handled by :feature:llm in Module 4). * * ## Download Verification * * When user adds a custom model by URL: *   1. Catalog validates URL format (HTTPS, GGUF extension) *   2. User taps "Download" → :feature:llm downloads the file *   3. SHA256 checksum verified (if user provided one) *   4. File size + GGUF header validated *   5. Model entry marked as "downloaded" in catalog *   6. User can now select it as default in Settings → AI Models * * ## Built-in Catalog * * Sensible defaults shipped with the app: *   - Qwen 2.5 0.5B (small, fast — recommended minimum) *   - Qwen 2.5 1.5B (better quality, still small) *   - Llama 3.2 1B (Meta's small model) *   - Phi-3.5 Mini (Microsoft's compact model) * * All are quantized to Q4_K_M (good quality/size balance) and downloaded * on-demand (no bundled model per ADR 0010). * * @see <a href="docs/spec/module2-spec-review.pdf">§8.5 Local Model Catalog</a> */@Singletonclass LocalLlmModelCatalog @Inject constructor() {    private val modelsById = ConcurrentHashMap<String, LocalLlmModel>()    init {        // Initialize with built-in catalog        for (model in BuiltInLocalModels.ALL) {            modelsById[model.id] = model        }    }    /**     * Get all models (built-in + user-added), in display order.     *     * Order: built-in models first (smallest to largest), then user-added     * models sorted alphabetically by display name.     */    fun getAll(): List<LocalLlmModel> {        val builtIn = BuiltInLocalModels.ALL.mapNotNull { modelsById[it.id] }        val userAdded = modelsById.values            .filter { !BuiltInLocalModels.isBuiltIn(it.id) }            .sortedBy { it.displayName.lowercase() }        return builtIn + userAdded    }    /**     * Get all downloaded models (files present on device).     */    fun getDownloaded(): List<LocalLlmModel> = getAll().filter { it.isDownloaded }    /**     * Get a single model by ID.     */    fun getById(id: String): LocalLlmModel? = modelsById[id]    /**     * Get the user's selected default model (or first built-in if none selected).     */    fun getDefault(): LocalLlmModel? =        modelsById.values.find { it.isDefault } ?: BuiltInLocalModels.DEFAULT_MODEL    /**     * Add a new user-defined model.     *     * Used when user enters a custom GGUF URL in Settings → AI Models → Add Model.     *     * @return Success with the added model, or Failure if validation fails     */    fun addUserModel(model: LocalLlmModel): Result<LocalLlmModel> {        val correlationId = CorrelationId.generate()        // Validate ID        if (!model.id.startsWith(LocalLlmModel.CUSTOM_PREFIX)) {            return Result.Failure(                error = AppError.Configuration.InvalidProviderConfig(                    reason = "User-added model ID must start with '${LocalLlmModel.CUSTOM_PREFIX}'",                ),                correlationId = correlationId,                durationNanos = 0,            )        }        if (modelsById.containsKey(model.id)) {            return Result.Failure(                error = AppError.Configuration.ProviderAlreadyExists(model.id),                correlationId = correlationId,                durationNanos = 0,            )        }        // Validate URL format if downloadUrl is provided        model.downloadUrl?.let { url ->            val urlError = validateDownloadUrl(url)            if (urlError != null) {                return Result.Failure(                    error = AppError.Configuration.InvalidProviderConfig(reason = urlError),                    correlationId = correlationId,                    durationNanos = 0,                )            }        }        val withTimestamp = model.copy(            isBuiltIn = false,            updatedAtEpochMs = System.currentTimeMillis(),        )        modelsById[model.id] = withTimestamp        Timber.tag("NOUS.L3").i(            "Added user model: %s (%s)",            withTimestamp.id,            withTimestamp.displayName,        )        return Result.Success(withTimestamp, correlationId, 0)    }    /**     * Update an existing model's metadata (e.g., mark as downloaded).     */    fun updateModel(model: LocalLlmModel): Result<LocalLlmModel> {        val correlationId = CorrelationId.generate()        val existing = modelsById[model.id]            ?: return Result.Failure(                error = AppError.Configuration.ProviderNotFound(model.id),                correlationId = correlationId,                durationNanos = 0,            )        val updated = model.copy(            isBuiltIn = existing.isBuiltIn,            updatedAtEpochMs = System.currentTimeMillis(),        )        modelsById[model.id] = updated        Timber.tag("NOUS.L3").i("Updated model: %s (downloaded=%s)", updated.id, updated.isDownloaded)        return Result.Success(updated, correlationId, 0)    }    /**     * Mark a model as downloaded (file present on device).     *     * Called by :feature:llm (Module 4) after successful download.     */    fun markDownloaded(modelId: String, filePath: String): Result<LocalLlmModel> {        val existing = modelsById[modelId]            ?: return Result.Failure(                error = AppError.Configuration.ProviderNotFound(modelId),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        return updateModel(existing.copy(            isDownloaded = true,            localFilePath = filePath,        ))    }    /**     * Mark a model as not downloaded (file deleted).     */    fun markNotDownloaded(modelId: String): Result<LocalLlmModel> {        val existing = modelsById[modelId]            ?: return Result.Failure(                error = AppError.Configuration.ProviderNotFound(modelId),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        return updateModel(existing.copy(            isDownloaded = false,            localFilePath = null,        ))    }    /**     * Set a model as the default (unsets previous default).     */    fun setDefault(modelId: String): Result<LocalLlmModel> {        val correlationId = CorrelationId.generate()        val target = modelsById[modelId]            ?: return Result.Failure(                error = AppError.Configuration.ProviderNotFound(modelId),                correlationId = correlationId,                durationNanos = 0,            )        if (!target.isDownloaded) {            return Result.Failure(                error = AppError.Configuration.InvalidProviderConfig(                    reason = "Cannot set '$modelId' as default — not downloaded yet",                ),                correlationId = correlationId,                durationNanos = 0,            )        }        // Unset all other defaults        for ((id, model) in modelsById) {            if (model.isDefault && id != modelId) {                modelsById[id] = model.copy(isDefault = false)            }        }        // Set new default        modelsById[modelId] = target.copy(isDefault = true)        Timber.tag("NOUS.L3").i("Default model set: %s", modelId)        return Result.Success(modelsById[modelId] ?: return Result.Failure(            error = com.roshan.persona.common.AppError.Llm.ModelMissing(modelId),            correlationId = correlationId,            durationNanos = 0,        ), correlationId, 0)    }    /**     * Delete a user-added model from the catalog.     *     * Built-in models CANNOT be deleted — only marked as not downloaded.     */    fun deleteUserModel(modelId: String): Result<Unit> {        val correlationId = CorrelationId.generate()        val existing = modelsById[modelId]            ?: return Result.Failure(                error = AppError.Configuration.ProviderNotFound(modelId),                correlationId = correlationId,                durationNanos = 0,            )        if (existing.isBuiltIn) {            return Result.Failure(                error = AppError.Configuration.ProviderBuiltinCannotDelete(modelId),                correlationId = correlationId,                durationNanos = 0,            )        }        modelsById.remove(modelId)        Timber.tag("NOUS.L3").i("Deleted user model: %s", modelId)        return Result.Success(Unit, correlationId, 0)    }    /**     * Number of total models in catalog.     */    fun totalCount(): Int = modelsById.size    /**     * Number of downloaded models.     */    fun downloadedCount(): Int = modelsById.values.count { it.isDownloaded }    // ─── Internal ────────────────────────────────────────────────────────    private fun validateDownloadUrl(url: String): String? {        if (!url.startsWith("https://")) {            return "Download URL must use HTTPS: $url"        }        if (!url.lowercase().endsWith(".gguf") && !url.contains(".gguf?")) {            return "URL must point to a .gguf file: $url"        }        return null    }}/** * A local LLM model entry in the catalog. */data class LocalLlmModel(    /** Stable unique ID (e.g., "qwen2.5-0.5b", "custom_my-llama"). */    val id: String,    /** Display name (e.g., "Qwen 2.5 0.5B (Q4)"). */    val displayName: String,    /** Optional download URL (HTTPS, .gguf file). Null for sideloaded-only models. */    val downloadUrl: String?,    /** Optional SHA256 checksum of the GGUF file (for download verification). */    val sha256: String?,    /** Estimated file size in bytes (for showing download progress). */    val sizeBytes: Long,    /** Maximum context length in tokens (model-specific). */    val contextLength: Int,    /** Quantization level (e.g., "Q4_K_M", "Q5_K_M", "Q8_0", "F16"). */    val quantization: String,    /** Architecture (e.g., "qwen2", "llama", "phi3"). Used by llama.cpp. */    val architecture: String,    /** Whether the file is present on device. */    val isDownloaded: Boolean = false,    /** Path to the downloaded GGUF file (null if not downloaded). */    val localFilePath: String? = null,    /** Whether this is the user's selected default model. */    val isDefault: Boolean = false,    /** True for built-in catalog entries, false for user-added. */    val isBuiltIn: Boolean = false,    /** When this entry was last updated (epoch millis). */    val updatedAtEpochMs: Long = 0L,    /** Optional description shown in UI. */    val description: String? = null,) {    init {        require(id.isNotBlank()) { "Model ID cannot be blank" }        require(displayName.isNotBlank()) { "Display name cannot be blank" }        require(sizeBytes > 0) { "Size must be positive, was $sizeBytes" }        require(contextLength in 512..1_000_000) {            "Context length must be 512-1_000_000, was $contextLength"        }        require(quantization.isNotBlank()) { "Quantization cannot be blank" }        require(architecture.isNotBlank()) { "Architecture cannot be blank" }    }    companion object {        /** Prefix for user-added model IDs. */        const val CUSTOM_PREFIX = "custom_"    }}/** * Built-in local LLM catalog. * * Curated list of recommended GGUF models. All quantized to Q4_K_M for * good quality/size balance. User can download any of these, or add * their own custom URLs. * * URLs point to Hugging Face repos — real URLs to be added in Module 4 * when the downloader is implemented. For now, URLs are placeholders. */object BuiltInLocalModels {    /** Smallest viable model — recommended minimum for first launch. */    val QWEN_2_5_0_5B = LocalLlmModel(        id = "qwen2.5-0.5b",        displayName = "Qwen 2.5 0.5B (Q4)",        downloadUrl = "https://huggingface.co/Qwen/Qwen2.5-0.5B-Instruct-GGUF/resolve/main/qwen2.5-0.5b-instruct-q4_k_m.gguf",        sha256 = null,  // populated in Module 4        sizeBytes = 500L * 1024 * 1024,  // ~500 MB        contextLength = 4_096,        quantization = "Q4_K_M",        architecture = "qwen2",        isBuiltIn = true,        description = "Smallest viable model. Fast inference, low memory. Recommended for first-time setup.",    )    /** Better quality, still small enough for mid-range phones. */    val QWEN_2_5_1_5B = LocalLlmModel(        id = "qwen2.5-1.5b",        displayName = "Qwen 2.5 1.5B (Q4)",        downloadUrl = "https://huggingface.co/Qwen/Qwen2.5-1.5B-Instruct-GGUF/resolve/main/qwen2.5-1.5b-instruct-q4_k_m.gguf",        sha256 = null,        sizeBytes = 1_200L * 1024 * 1024,  // ~1.2 GB        contextLength = 8_192,        quantization = "Q4_K_M",        architecture = "qwen2",        isBuiltIn = true,        description = "Better quality than 0.5B, still runs on mid-range phones (4GB+ RAM).",    )    /** Meta's small model. */    val LLAMA_3_2_1B = LocalLlmModel(        id = "llama-3.2-1b",        displayName = "Llama 3.2 1B (Q4)",        downloadUrl = "https://huggingface.co/meta-llama/Llama-3.2-1B-Instruct-GGUF/resolve/main/llama-3.2-1b-instruct-q4_k_m.gguf",        sha256 = null,        sizeBytes = 1_000L * 1024 * 1024,  // ~1 GB        contextLength = 8_192,        quantization = "Q4_K_M",        architecture = "llama",        isBuiltIn = true,        description = "Meta's compact model. Good for general Q&A on devices with 4GB+ RAM.",    )    /** Microsoft's compact model — punches above its weight. */    val PHI_3_5_MINI = LocalLlmModel(        id = "phi-3.5-mini",        displayName = "Phi-3.5 Mini (Q4)",        downloadUrl = "https://huggingface.co/microsoft/Phi-3.5-mini-instruct-gguf/resolve/main/Phi-3.5-mini-instruct-q4_k_m.gguf",        sha256 = null,        sizeBytes = 2_200L * 1024 * 1024,  // ~2.2 GB        contextLength = 8_192,        quantization = "Q4_K_M",        architecture = "phi3",        isBuiltIn = true,        description = "Microsoft's compact model. Better reasoning than its size suggests. Needs 6GB+ RAM.",    )    /**     * All built-in models, smallest first (so default is the smallest).     */    val ALL: List<LocalLlmModel> = listOf(        QWEN_2_5_0_5B,        LLAMA_3_2_1B,        QWEN_2_5_1_5B,        PHI_3_5_MINI,    )    /**     * Default model — used as fallback when no user-set default exists.     * Per ADR 0010, this is the recommended minimum for first launch.     */    val DEFAULT_MODEL: LocalLlmModel = QWEN_2_5_0_5B    /**     * Whether [id] is a built-in model ID.     */    fun isBuiltIn(id: String): Boolean = ALL.any { it.id == id }    /**     * Look up a built-in model by ID.     */    fun byId(id: String): LocalLlmModel? = ALL.find { it.id == id }}